cat > dbg-caps2.mjs <<'EOF'
import puppeteer from 'puppeteer-core';
import { spawn } from 'child_process';
const port = 3972;
const srv = spawn('node', ['server/index.js'], { cwd: '../app', env: { ...process.env, PORT: String(port) }, stdio: 'pipe' });
await new Promise(r => setTimeout(r, 900));
const browser = await puppeteer.launch({ executablePath: '/usr/bin/google-chrome-stable', headless: 'new',
  args: ['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'],
  defaultViewport: { width: 1280, height: 720 } });
const page = await browser.newPage();
page.on('pageerror', e => console.log('ERR', e.message));
await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: 'networkidle0' });
await page.waitForFunction('window.GAME && window.GAME.ready');
await page.evaluate(() => {
  GAME.test.setSetting('graphics.preset', 'ultra');
  GAME.test.setSetting('graphics.resolutionScale', 1.0);
  GAME.test.start('vector'); GAME.test.skipBuy();
  const g = GAME.game;
  for (let i = 0; i < Math.min(4, g.bots.length); i++) {
    g.bots[i].pos = [-3 + i * 2, 0, 15 - (i % 2)];
    g.bots[i].yaw = Math.PI + (i - 1.5) * 0.3;
  }
  GAME.test.pose(0, 0, 21, 0, 0.02);
});
await new Promise(r => setTimeout(r, 2500));
const vis = await page.evaluate(() => {
  const ids = ['buy-menu', 'scoreboard', 'respawn-overlay', 'phase-banner', 'room-banner'];
  return ids.map(id => {
    const el = document.getElementById(id);
    const cs = getComputedStyle(el);
    return `${id}: display=${cs.display} rect=${JSON.stringify(el.getBoundingClientRect())}`;
  }).join('\n');
});
console.log(vis);
await page.screenshot({ path: 'dbg-ultra.png' });
await browser.close(); srv.kill();
EOF
node dbg-caps2.mjs
